# Gerando o código AJAX
ajax_code = f"""
fetch('{url}', {{
    method: 'POST',
    headers: {{
        'Content-Type': 'application/json'
    }},
    body: JSON.stringify({json.dumps(data)})
}})
.then(response => response.json())
.then(data => {{
    console.log('Sucesso:', data);
}})
.catch((error) => {{
    console.error('Erro:', error);
}});
"""

# Caminho para salvar o arquivo na raiz do C:
filename = r"C:\ajax_request.js"

# Salvando o código AJAX no arquivo
with open(filename, "w", encoding="utf-8") as file:
    file.write(ajax_code)

print(f"Código AJAX salvo em {filename}")